Node detectCycleStart(Node head) {
    Node slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) {                 // cycle confirmed
            slow = head;                    // reset one pointer
            while (slow != fast) { slow = slow.next; fast = fast.next; }
            return slow;                    // entry point of the loop
        }
    }
    return null;                            // no cycle
}

// 1->2->3->4->5->3(back): meet inside loop, reset, both walk -> meet at 3
```

```java
Node reverseRec(Node head) {
    if (head == null || head.next == null) return head;  // base case
    Node newHead = reverseRec(head.next);   // reverse the rest first
    head.next.next = head;                  // flip the link back
    head.next = null;
    return newHead;
}
// Clean, but n nested calls => O(n) call-stack space.
```

```java
Node reverse(Node head) {
    Node prev = null, curr = head;
    while (curr != null) {
        Node next = curr.next;   // save the rest
        curr.next = prev;        // flip
        prev = curr;             // advance
        curr = next;
    }
    return prev;                 // new head
}
// 1->2->3 becomes 3->2->1, using only a few pointers => O(1) space.
```

```java
class Node { int val; Node next; Node(int v){ val = v; } }

Node middle(Node head) {
    Node slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;          // +1
        fast = fast.next.next;     // +2
    }
    return slow;                   // middle (2nd middle if even length)
}

// 1->2->3->4->5 : slow 1->2->3, fast 1->3->5(end) => middle 3
// 1->2->3->4    : slow 1->2->3, fast 1->3->null    => middle 3 (second)
```

```java
class SNode { int val; SNode next; }

// To delete 'target', we must find its PREVIOUS node by walking - O(n)
void delete(SNode head, SNode target) {
    SNode prev = head;
    while (prev != null && prev.next != target) prev = prev.next;  // O(n)
    if (prev != null) prev.next = target.next;   // relink past target
}
```

```java
class DNode { int val; DNode prev, next; }

// We already have 'target' and its prev pointer, so no searching - O(1)
void delete(DNode target) {
    if (target.prev != null) target.prev.next = target.next;
    if (target.next != null) target.next.prev = target.prev;
}                                              // O(1) relink both ways
```
The `prev` pointer is exactly what makes known-node deletion constant time.
